INSERT INTO `community_post` (`user_id`, `type`, `title`, `content`, `images`, `like_count`, `comment_count`, `status`, `audit_time`, `auditor_id`, `create_time`, `update_time`) VALUES
(3, 1, '西瓜拼团还差2人，速来！', '麒麟西瓜3.99一斤，比水果店便宜一半，拼3个瓜起送，还差2个人！', NULL, 8, 4, 1, NOW(), 1, '2026-10-15 09:20:00', NOW()),
(4, 2, '巨峰葡萄真的甜', '昨天到的巨峰葡萄，颗颗饱满，孩子一口气吃了一串，推荐！', '["/upload/grape.jpg"]', 12, 3, 1, NOW(), 1, '2026-10-15 11:30:00', NOW()),
(5, 1, '五花肉团购，红烧肉的约起', '猪五花肉28一公斤，我买了2公斤做了红烧肉，肥而不腻，有没有邻居再拼一单？', NULL, 6, 5, 1, NOW(), 1, '2026-10-15 14:10:00', NOW()),
(6, 2, '大闸蟹到了，鲜活！', '阳澄湖大闸蟹，到货全是活的，晚上蒸了，蟹黄很多。', '["/upload/crab.jpg"]', 15, 6, 1, NOW(), 1, '2026-10-15 18:40:00', NOW()),
(7, 1, '三文鱼拼单，一个人吃不完', '冰鲜三文鱼88一公斤，刺身级的，想找2个邻居分一条。', NULL, 4, 3, 1, NOW(), 1, '2026-10-16 08:50:00', NOW()),
(1, 2, '临期特价的香蕉太值了', '临期专区买的香蕉打7折，其实还挺新鲜的，省钱小能手就是我。', NULL, 9, 2, 1, NOW(), 1, '2026-10-16 10:20:00', NOW()),
(3, 2, '西兰花很新鲜，减脂餐安排', '云南来的西兰花，花球紧实，水煮蘸酱油就很好吃。', NULL, 5, 1, 1, NOW(), 1, '2026-10-16 12:30:00', NOW()),
(4, 1, '大米拼团，家家都需要', '五常大米59.9一袋5kg，这个米真的香，拼团的邻居留言。', NULL, 7, 4, 1, NOW(), 1, '2026-10-16 15:00:00', NOW()),
(5, 2, '自提点取货很方便', '下班顺路在幸福里自提点拿的菜，团长人很好还帮忙装袋，推荐大家都选自提。', NULL, 11, 3, 1, NOW(), 1, '2026-10-16 19:20:00', NOW()),
(6, 1, '牛腱子卤起来，拼吗', '内蒙古牛腱子59一公斤，准备卤一锅，有邻居一起拼吗？', NULL, 3, 2, 1, NOW(), 1, '2026-10-17 09:00:00', NOW()),
(7, 2, '猕猴桃放两天就甜了', '徐香猕猴桃，收到硬一点，和苹果放一起两天就软甜了。', '["/upload/kiwi.jpg"]', 6, 2, 1, NOW(), 1, '2026-10-17 10:40:00', NOW()),
(1, 1, '预售苹果下单了，期待', '红富士预售5.5一斤，比现货便宜，已下单10斤，坐等25号发货。', NULL, 8, 3, 1, NOW(), 1, '2026-10-17 13:15:00', NOW()),
(3, 2, '黄瓜生吃清脆爽口', '水果黄瓜真的可以直接当水果吃，脆甜脆甜的。', NULL, 4, 1, 1, NOW(), 1, '2026-10-17 16:30:00', NOW()),
(4, 1, '鸡蛋团购第二波，没抢到的来', '上次鸡蛋团购没抢到的邻居，团长说人够就开第二波，报名！', NULL, 13, 5, 1, NOW(), 1, '2026-10-17 18:00:00', NOW()),
(5, 2, '凉拌黑木耳，夏日必备', '东北黑木耳泡发后凉拌，脆嫩爽口，250g能吃好多次。', NULL, 5, 2, 1, NOW(), 1, '2026-10-18 08:30:00', NOW()),
(6, 1, '鲈鱼拼单，清蒸最鲜', '鲜活鲈鱼32一公斤，清蒸最鲜了，有一起拼的邻居吗？', NULL, 4, 3, 1, NOW(), 1, '2026-10-18 10:00:00', NOW()),
(7, 2, '玉米油炒菜很清香', '换了玉米胚芽油，炒出来的菜清爽不油腻，推荐。', NULL, 3, 1, 1, NOW(), 1, '2026-10-18 12:20:00', NOW()),
(1, 2, '社区团购太方便了', '自从有了这个平台，买菜不用跑超市了，今天下单明天自提，新鲜还便宜。', NULL, 16, 4, 1, NOW(), 1, '2026-10-18 14:40:00', NOW()),
(3, 1, '土豆洋葱拼一单，做咖喱', '土豆+洋葱拼单，周末做咖喱鸡，有邻居一起吗？', NULL, 5, 2, 1, NOW(), 1, '2026-10-18 16:50:00', NOW()),
(4, 2, '火龙果颜值太高了', '红心火龙果切开颜值绝了，打果汁特别好看。', '["/upload/dragonfruit.jpg"]', 7, 2, 1, NOW(), 1, '2026-10-19 08:20:00', NOW()),
(5, 1, '鸭胸肉健身餐拼单', '樱桃谷鸭胸22一公斤，健身的邻居看过来，拼一单。', NULL, 4, 1, 1, NOW(), 1, '2026-10-19 09:40:00', NOW()),
(6, 2, '胡萝卜炖牛腩绝配', '用平台买的胡萝卜炖了牛腩，胡萝卜比肉还甜。', NULL, 6, 3, 1, NOW(), 1, '2026-10-19 11:10:00', NOW()),
(7, 1, '面粉拼单做包子', '高筋面粉19.9一袋，周末包包子，有邻居拼面粉的吗？', NULL, 3, 2, 1, NOW(), 1, '2026-10-19 13:30:00', NOW()),
(1, 2, '给团长点赞', '今天下雨，团长还在自提点等大家取货，辛苦了！', NULL, 20, 6, 1, NOW(), 1, '2026-10-19 15:00:00', NOW()),
(3, 2, '绿豆汤熬起来', '脱皮绿豆质量真好，熬了绿豆汤，沙沙的。', NULL, 4, 1, 1, NOW(), 1, '2026-10-19 17:20:00', NOW()),
(4, 1, '基围虾拼单，白灼最鲜', '鲜活基围虾39.9一斤，白灼蘸酱油，有拼的邻居吗？', NULL, 6, 3, 1, NOW(), 1, '2026-10-19 18:40:00', NOW()),
(5, 2, '平台蔬菜比超市新鲜', '对比过了，平台的绿叶菜比楼下超市新鲜，价格还便宜。', NULL, 9, 2, 1, NOW(), 1, '2026-10-20 07:30:00', NOW()),
(6, 1, '拼车买西瓜，皮薄沙甜', '麒麟西瓜真的沙甜，再拼一车，要的留言。', NULL, 5, 2, 1, NOW(), 1, '2026-10-20 08:40:00', NOW()),
(7, 2, '第一次用自提码，好高级', '今天取货用了自提码，报数字就行，不用翻手机找订单，方便。', NULL, 8, 3, 1, NOW(), 1, '2026-10-20 09:50:00', NOW()),
(1, 1, '周末火锅食材拼单召集', '周末想在家吃火锅，拼虾、牛肉、蔬菜，要的邻居楼下集合！', NULL, 10, 5, 1, NOW(), 1, '2026-10-20 10:30:00', NOW()),
(3, 2, '溯源功能不错，吃得放心', '看了西红柿的溯源信息，产地种植户都有，吃着放心多了。', NULL, 7, 2, 1, NOW(), 1, '2026-10-20 11:20:00', NOW()),
(4, 2, '求推荐好做的菜谱', '刚搬来社区，请问大家都买什么菜？求推荐简单好做的。', NULL, 2, 4, 1, NOW(), 1, '2026-10-20 12:00:00', NOW()),
(5, 1, '大闸蟹下一波什么时候', '大闸蟹太好吃了，问下团长下一波团购什么时候开？', NULL, 6, 3, 1, NOW(), 1, '2026-10-20 12:30:00', NOW()),
(6, 1, '有没有人拼三文鱼', '想吃三文鱼了，88一公斤有点多，找两个邻居分。', NULL, 0, 0, 0, NULL, NULL, '2026-10-20 13:00:00', NOW()),
(7, 2, '晒一下今天买的菜', '今天买了一大袋，才花了50多，够吃三天了。', '["/upload/spinach.jpg"]', 0, 0, 0, NULL, NULL, '2026-10-20 13:20:00', NOW()),
(1, 1, '拼单带鱼，红烧带鱼', '舟山带鱼45一公斤，红烧特别香，找邻居拼单。', NULL, 0, 0, 0, NULL, NULL, '2026-10-20 13:40:00', NOW()),
(3, 2, '第一次在社区平台买菜体验', '新人报道，第一次下单，流程挺顺的，等明天自提。', NULL, 0, 0, 0, NULL, NULL, '2026-10-20 14:00:00', NOW()),
(4, 1, '拼单大米和油', '家里米油都没了，有邻居一起拼大米和玉米油吗？', NULL, 0, 0, 0, NULL, NULL, '2026-10-20 14:20:00', NOW()),
(5, 2, '西瓜真的很甜', '跟风买的麒麟西瓜，全家都说甜。', NULL, 0, 0, 0, NULL, NULL, '2026-10-20 14:40:00', NOW()),
(6, 1, '团购鸡蛋转让一份', '团购多抢了一份鸡蛋，有要的邻居吗？原价转。', NULL, 0, 0, 0, NULL, NULL, '2026-10-20 15:00:00', NOW()),
(7, 2, '求拼单群', '有没有咱们社区的拼单微信群？拉我一下。', NULL, 0, 0, 0, NULL, NULL, '2026-10-20 15:20:00', NOW()),
(1, 2, '今天的虾很新鲜', '中午到的基围虾，活蹦乱跳的。', NULL, 0, 0, 0, NULL, NULL, '2026-10-20 15:40:00', NOW()),
(3, 1, '拼单鸡腿肉', '想拼点鸡腿肉做照烧鸡腿饭，有一起的吗？', NULL, 0, 0, 0, NULL, NULL, '2026-10-20 16:00:00', NOW());
